"""
  Helper sorting the named modules into existing and not existing.
  """
def _find_imports(*args: Any) -> object {
    import importlib;
    exists = {True: [], False: []};
    for name in args {
        name = name.replace('-', '_');
        try {
            importlib.import_module(name);
            exists[True].append(name);
        } except ImportError {
            exists[False].append(name);
        }
    }
    return exists;
}

